using System.Security.Cryptography;
using System.Text;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
using QRCoder;
namespace VelvetVault;

public static class VaultAccess {
 public static string NewKey(){const string alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";byte[] bytes=RandomNumberGenerator.GetBytes(20);var text=new StringBuilder();int buffer=0,bits=0;foreach(byte value in bytes){buffer=(buffer<<8)|value;bits+=8;while(bits>=5){bits-=5;text.Append(alphabet[(buffer>>bits)&31]);}}CryptographicOperations.ZeroMemory(bytes);return text.ToString();}
 public static string SetupUri(string key)=>"otpauth://totp/Vault%3APassword%20Vault?secret="+Uri.EscapeDataString(key)+"&issuer=Vault&algorithm=SHA1&digits=6&period=30";
 public static bool Verify(string key,string code,long unixSeconds){
  if(code.Length!=6||code.Any(c=>c<'0'||c>'9'))return false;
  var account=new TotpAccount{Name="Vault",Secret=key};byte[] entered=Encoding.ASCII.GetBytes(code);bool match=false;for(int step=-1;step<=1;step++){long when=unixSeconds+step*30;if(when<0)continue;match|=CryptographicOperations.FixedTimeEquals(entered,Encoding.ASCII.GetBytes(Totp.Code(account,when)));}return match;
 }
 public static bool Unlock(Window? owner,string key,string? vaultPath=null){if(key.Length==0)return true;return Dialog(owner,key,false,null,vaultPath).ShowDialog()==true;}
 public static void Setup(Window owner,Func<string,bool> save,string? vaultPath=null){string key=NewKey();if(Dialog(owner,key,true,save).ShowDialog()==true){if(vaultPath!=null)RecoveryCodes.GenerateAndShow(owner,vaultPath);else VaultPrompt.Show(owner,"2FA enabled","Your setup is saved.",false);}}
 public static Window Dialog(Window? owner,string key,bool setup,Func<string,bool>? save,string? vaultPath=null){
  var window=VaultUI.Window(owner,setup?"Vault - Setup 2FA":"Vault - Unlock",430,setup?590:330);window.ResizeMode=ResizeMode.NoResize;window.ShowInTaskbar=owner==null;NameScope.SetNameScope(window,new NameScope());
  var root=VaultUI.Grid(new GridLength(8),new GridLength(1,GridUnitType.Star),new GridLength(48));root.Margin=new Thickness(14,2,14,6);root.Children.Add(new MotionRail{Height=3});
  var body=new StackPanel{Margin=new Thickness(17)};body.Children.Add(VaultUI.Label(setup?"SCAN WITH GOOGLE AUTHENTICATOR":"OFFLINE / AUTHENTICATOR VERIFICATION",8));body.Children.Add(new TextBlock{Text=setup?"Scan this QR, then enter the 6-digit code to enable the opening check.":"Enter the current 6-digit code from Google Authenticator to open Vault.",FontSize=12,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,10,0,12)});
  QRCodeData? data=null;if(setup){using var generator=new QRCodeGenerator();data=generator.CreateQrCode(SetupUri(key),QRCodeGenerator.ECCLevel.M);body.Children.Add(new AccountQr(data){Height=270,Margin=new Thickness(0,0,0,12)});body.Children.Add(VaultUI.Label("Keep access to this authenticator account. You will get recovery codes after confirming setup.",9));}
  var input=new TextBox{Foreground=Palette.Ink,FontFamily=new FontFamily("Consolas"),FontSize=24,MaxLength=6,TextAlignment=TextAlignment.Center,BorderThickness=new Thickness(0),Padding=new Thickness(0),Background=Brushes.Transparent};window.RegisterName("CodeInput",input);body.Children.Add(new Border{Child=FieldCaret.Wrap(input),BorderBrush=Palette.Ink,BorderThickness=new Thickness(1.2),CornerRadius=new CornerRadius(6),Padding=new Thickness(9,6,9,6),Margin=new Thickness(0,12,0,0)});
  var error=new TextBlock{FontSize=10,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,7,0,0)};window.RegisterName("CodeError",error);body.Children.Add(error);bool usingRecovery=false;
  if(!setup&&vaultPath!=null&&VaultStorage.LoadRecoveryHashes(vaultPath).Count>0){var recoveryButton=new Button{Content="USE RECOVERY CODE",FontSize=10,Padding=new Thickness(9,5,9,5),HorizontalAlignment=HorizontalAlignment.Left,Margin=new Thickness(0,8,0,0)};window.RegisterName("RecoveryMode",recoveryButton);recoveryButton.Click+=(_,_)=>{usingRecovery=!usingRecovery;input.Clear();input.MaxLength=usingRecovery?60:6;input.FontSize=usingRecovery?12:24;error.Text=usingRecovery?"Enter one unused recovery code.":"Enter your current authenticator code.";recoveryButton.Content=usingRecovery?"USE AUTHENTICATOR":"USE RECOVERY CODE";input.Focus();};body.Children.Add(recoveryButton);}
  var frame=new RetroFrame{Child=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Hidden}};Grid.SetRow(frame,1);root.Children.Add(frame);
  var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Center};var cancel=new Button{Content="CANCEL",IsCancel=true,FontSize=10};cancel.Click+=(_,_)=>window.DialogResult=false;window.RegisterName("CancelCode",cancel);var verify=new Button{Content=setup?"ENABLE 2FA":"UNLOCK",IsDefault=true,FontSize=10,Background=Palette.Ink,Foreground=Palette.Paper,Margin=new Thickness(0)};window.RegisterName("VerifyCode",verify);
  int failures=0;DateTimeOffset blockedUntil=DateTimeOffset.MinValue;var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};
  timer.Tick+=(_,_)=>{int left=(int)Math.Ceiling((blockedUntil-DateTimeOffset.UtcNow).TotalSeconds);if(left<=0){timer.Stop();verify.IsEnabled=true;error.Text="Try your current authenticator code.";}else error.Text=$"Please wait {left}s before trying again.";};
  verify.Click+=(_,_)=>{if(DateTimeOffset.UtcNow<blockedUntil)return;bool accepted;try{accepted=usingRecovery&&vaultPath!=null?RecoveryCodes.Consume(vaultPath,key,input.Text):Verify(key,input.Text.Trim(),DateTimeOffset.UtcNow.ToUnixTimeSeconds());}catch{error.Text="Could not verify or save. Please try again.";return;}if(!accepted){input.Clear();error.Text=usingRecovery?"Recovery code is invalid or already used.":"Code did not match. Check your phone and computer time.";if(++failures>=5){failures=0;blockedUntil=DateTimeOffset.UtcNow.AddSeconds(30);verify.IsEnabled=false;error.Text="Please wait 30s before trying again.";timer.Start();}return;}if(setup&&(save==null||!save(key))){error.Text="Could not save. 2FA has not been enabled.";return;}window.DialogResult=true;};actions.Children.Add(cancel);actions.Children.Add(verify);Grid.SetRow(actions,2);root.Children.Add(actions);VaultChrome.Apply(window,root,setup?"SETUP 2FA":"UNLOCK VAULT");window.Loaded+=(_,_)=>{window.Activate();input.Focus();};window.Closed+=(_,_)=>{timer.Stop();data?.Dispose();};return window;
 }
}
public sealed class VaultAccessPanel : StackPanel {
 readonly TextBlock state=new(){FontFamily=new FontFamily("Consolas"),FontSize=11,TextAlignment=TextAlignment.Center,Margin=new Thickness(0,12,0,9)};
 readonly Button action;readonly Button recovery;Action? clicked;Action? manageRecovery;
 public VaultAccessPanel(){VerticalAlignment=VerticalAlignment.Center;Margin=new Thickness(0,8,0,8);Children.Add(new TextBlock{Text="2FA",FontFamily=new FontFamily(new Uri("pack://application:,,,/VelvetVault;component/"),"./Fonts/#Saira Stencil"),FontSize=39,TextAlignment=TextAlignment.Center});Children.Add(new TextBlock{Text="GOOGLE AUTHENTICATOR",FontSize=9,TextAlignment=TextAlignment.Center});Children.Add(new VaultSeal{Width=70,Height=70,Margin=new Thickness(0,12,0,0)});Children.Add(state);Children.Add(new TextBlock{Text="SCAN VAULT'S QR\nENTER A CODE TO OPEN",FontFamily=new FontFamily("Consolas"),FontSize=9,TextAlignment=TextAlignment.Center,Margin=new Thickness(0,0,0,14)});action=new Button{FontSize=10,FontWeight=FontWeights.Bold,Padding=new Thickness(10,7,10,7),HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0)};action.Click+=(_,_)=>clicked?.Invoke();Children.Add(action);recovery=new Button{Content="RECOVERY CODES",FontSize=9,Padding=new Thickness(9,5,9,5),HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,7,0,0)};recovery.Click+=(_,_)=>manageRecovery?.Invoke();Children.Add(recovery);}
 public void Configure(bool enabled,Action setup,Action disable,Action? recoveryAction=null){recovery.Visibility=enabled?Visibility.Visible:Visibility.Collapsed;manageRecovery=recoveryAction;state.Text=enabled?"ON / REQUIRED AT OPEN":"OFF / NOT ENABLED";state.Foreground=Palette.Muted;action.Content=enabled?"DISABLE 2FA":"+ SETUP QR";clicked=enabled?disable:setup;}
}
